typedef unsigned long big_int;

class stringx;

class string_buf {
    friend class stringx;
    friend bool operator==(const stringx &left, const stringx &right);

    big_int *data;
    int ref_count;
    int char_length;
    int block_length;
    int max_blocks;

public:
    bool is_equal(const string_buf &other) const
    {
        if (other.block_length != block_length)
            return false;
        for (int index = 0; index < block_length; ++index)
        {
            if (!(other.data[index] == data[index]))
                return false;
        }
        return true;
    }
};

class stringx {
    friend bool operator==(const stringx &left, const stringx &right);

    char *chars;
    string_buf *my_buf;

public:
    stringx();
    stringx(const stringx &other);
    ~stringx();
};

inline bool operator==(const stringx &left, const stringx &right)
{
    return left.my_buf->is_equal(*right.my_buf);
}

inline bool operator!=(const stringx &left, const stringx &right)
{
    return !(left == right);
}

class chunk_file;
class entity;

class signaller {
    unsigned int flags;
    void *signals;

public:
    signaller();
    virtual ~signaller();
    virtual bool is_an_entity() const { return false; }
    virtual bool is_a_trigger() const { return false; }
    virtual void raise_signal(unsigned int signal_id) const;

private:
