protected:
    virtual const char *get_signal_name(unsigned short signal_id) const;
};

class vector3d {
    float x;
    float y;
    float z;
};

class trigger : public signaller {
public:
    trigger(const stringx &id);
    virtual void read(chunk_file &file) {}
    virtual bool triggered(entity *) { return false; }
    virtual void update_region() {}
    virtual bool is_a_trigger() const { return true; }
    virtual const vector3d &get_abs_position() const;

    void force_region(stringx id);

protected:
    entity *whodunnit;
    stringx id;
    trigger *next;
    char in_regions[12];
    bool static_regions;
    bool active;
    bool occupied;
    bool use_any_char;
};

class region_trigger : public trigger {
public:
    region_trigger(const stringx &id);
    virtual void read(chunk_file &file);
    virtual bool triggered(entity *value);
    virtual void update_region();
};

void serial_in(chunk_file &file, stringx *value);
extern const stringx chunkend_label;

