__asm__(".equ serial_in__FR10chunk_fileP7stringx, 0x003369F8");
__asm__(".equ force_region__7triggerG7stringx, 0x0028DAA0");
__asm__(".equ chunkend_label, 0x0046B558");

void region_trigger::read(chunk_file &fs)
{
	stringx reg_id;
	for ( serial_in(fs,&reg_id); reg_id!=chunkend_label; serial_in(fs,&reg_id) )
